`,faqs:[{question:"Is Dodo Payments supported for SaaS subscription renewals?",answer:"Yes, all one-time and recurring events are processed automatically."}]},revenuecat:{slug:"revenuecat",name:"RevenueCat",category:"payment",categoryLabel:"Payment Provider",tagline:"In-app purchase & mobile subscription attribution for cross-platform apps.",description:"Connect iOS App Store and Google Play subscription events from RevenueCat to your web landing pages and attribution funnels.",icon:"thesvg-color:revenuecat",badge:"Mobile & Web",setupTime:"3 mins",metaTitle:"RevenueCat Analytics & Attribution - ClockTime",metaDescription:"Bridge web marketing campaigns to mobile in-app subscriptions with RevenueCat and ClockTime.",features:[{icon:"solar:smartphone-bold-duotone",title:"Web-to-App Conversion Tracking",description:"Connect web landing page clicks to mobile App Store subscription completions."},{icon:"solar:chart-2-bold-duotone",title:"Cross-Platform Cohorts",description:"Analyze web visitors who convert on iOS, Android, or Stripe Web seamlessly."}],content:`
